/**
 * Resolusi nama ikon → komponen. `fallbackName` dipakai bila `name` tak dikenal
 * (mis. "Wallet" untuk dompet, "Book" untuk pembukuan); terakhir jatuh ke Tag.
 */
export function resolveIcon(
  name?: string | null,
  fallbackName = "Tag",
): LucideIcon {
  return (
    (name ? ICON_COMPONENTS[name] : undefined) ??
    ICON_COMPONENTS[fallbackName] ??
    Tag
  );
}
